dur = {"OEM 요구사항 확정": 3, "앱 UI·내비 기능": 7, "서버 API": 5,
       "차량 신호 연동": 6, "통합 빌드": 1, "실차 검증": 4, "OEM 승인 시험": 2}
dep = {"앱 UI·내비 기능": ["OEM 요구사항 확정"], "서버 API": ["OEM 요구사항 확정"],
       "차량 신호 연동": ["OEM 요구사항 확정"],
       "통합 빌드": ["앱 UI·내비 기능", "서버 API", "차량 신호 연동"],
       "실차 검증": ["통합 빌드"], "OEM 승인 시험": ["실차 검증"]}
end, via = {}, {}
def f(t):
    if t not in end:
        best = max(dep.get(t, []), key=f, default=None)
        via[t] = best
        end[t] = (f(best) if best else 0) + dur[t]
    return end[t]
t, path = "OEM 승인 시험", []
total = f(t)
while t:
    path.append(t); t = via[t]
print(f"임계 경로 {total}주: " + " → ".join(reversed(path)))
for k in ["서버 API", "차량 신호 연동"]:
    print(f"{k} 여유 {f('앱 UI·내비 기능') - f(k)}주")

crit = {"치명": 0, "높음": 2, "보통": 15}
open_bugs = [("치명", "OEM-A"), ("높음", "OEM-A"), ("높음", "OEM-B"), ("높음", "OEM-A"),
             ("보통", "OEM-A")] + [("보통", "OEM-B")] * 9
for oem in ["OEM-A", "OEM-B"]:
    cnt = {k: sum(1 for s, o in open_bugs if s == k and o == oem) for k in crit}
    bad = [f"{k} {cnt[k]}>{crit[k]}" for k in crit if cnt[k] > crit[k]]
    print(oem, cnt, "→", ("No-Go: " + ", ".join(bad)) if bad else "Go")

fleet = {"3.2": 41000, "3.5": 120000, "4.0": 380000, "4.1": 260000}
api_of = {"3.2": "v1", "3.5": "v1", "4.0": "v2", "4.1": "v2"}
hit = sum(n for app, n in fleet.items() if api_of[app] == "v1")
total = sum(fleet.values())
print(f"v1 종료 시 깨지는 차 {hit:,}대 / {total:,}대 = {hit/total:.1%}")
